import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:]

    # Calculate character counts for each string
    char_counts = []
    for s in strings:
        counts = tuple(sorted(s))
        char_counts.append(counts)

    result = 0

    # For all pairs (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            c1, c2 = char_counts[i], char_counts[j]
            if c1 != c2:
                result += 1337
            else:
                if strings[i] == strings[j]:
                    result += 0  # Already equal
                else:
                    result += 1  # Same characters, need 1 operation

    return f"{result}\n"

if __name__ == "__main__":
    # Read from stdin in typical test scenarios
    import sys
    input_data = sys.stdin.read()
    print(solution(input_data))

