import math
import sys

def solution(input_data):
    l, r = map(int, input_data.strip().split())
    count = 0

    # Check for prime 2
    if l <= 2 <= r:
        count += 1

    # Precompute primes up to sqrt(r) for factorization
    sqrt_r = int(math.sqrt(r)) + 1
    is_prime_small = bytearray(sqrt_r + 1)

    for i in range(2, int(math.sqrt(sqrt_r)) + 1):
        if is_prime_small[i] == 0:
            for j in range(i*i, sqrt_r + 1, i):
                is_prime_small[j] = 1

    primes_small = []
    for i in range(2, sqrt_r + 1):
        if is_prime_small[i] == 0:
            primes_small.append(i)

    # Sieve to mark non-primes in the range [l, r]
    # We'll use a sieve only for checking primality
    # Process range in blocks to handle memory

    def is_prime_check(n):
        """Check if n is prime using precomputed primes"""
        if n < 2:
            return False
        for p in primes_small:
            if p * p > n:
                break
            if n % p == 0:
                return False
        return True

    def count_primes_in_segment(start, end):
        """Count primes ≡ 1 (mod 4) in [start, end]"""
        if start > end:
            return 0
        if end < 2:
            return 0

        segment_size = end - start + 1
        sieve = bytearray([0]) * ((segment_size // 2) + 1)  # Index by odd positions

        sieved = 0
        for p in primes_small:
            if p * p > end:
                break

            # Find the first multiple of p in [start, end]
            first_multiple = (start + (p - 1)) // p * p
            if first_multiple < p * p and p * p >= start and p * p <= end:
                first_multiple = p * p
            else:
                first_multiple = max(start, first_multiple)

            if first_multiple > end:
                continue

            # Mark multiples (only odd ones need tracking in our segmented sieve)
            for j in range(first_multiple, end + 1, p):
                if j % 2 == 1:  # Only mark odd numbers
                    # Calculate position in sieve
                    pos = (j - start) // 2
                    sieve[pos] = 1

        # Count unmarked numbers that are ≡ 1 (mod 4)
        # Map: numbers are 1-indexed in our sieve for odd numbers
        count = 0
        for i in range(0, min(segment_size, 3000000 // 2) + 1):
            if sieve[i] == 0:  # Potential prime
                actual_num = start + i * 2
                if actual_num > r:
                    break
                if actual_num >= 3:
                    # Check if 1 mod 4
                    if actual_num % 4 == 1:
                        count += 1

        return count

    # Split into reasonable chunks
    step = 100000  # Process 100k at a time
    count = 0
    for i in range(0, 10000000, step):
        end = min(r, l + step - 1)
        if end < l:
            break
        ret = count_primes_in_segment(l + i, end)
        count += ret

    return str(count) + '\n'

