    if n == 0:
        return ''

    players = []
    for i in range(n):
        parts = lines[i + 1].split()
        si, ri = int(parts[0]), int(parts[1])
        players.append((i + 1, si, ri))

    result = []

    for i in range(n):
        possible = True
        si, ri = players[i][1], players[i][2]

        for j in range(n):
            if i == j:
                continue

            sj, rj = players[j][1], players[j][2]

            # Person j dominates person i if j has equal or better speeds in both
            # and at least one strictly better.
            if sj >= si and rj >= ri:
                if sj > si or rj > ri:
                    possible = False
                    break

        if possible:
            result.append(players[i][0])

    return ' '.join(map(str, result)) + '\n'

