    def count_digits_upto(n):
        """Count digits in '123...n' (string concatenation of 1 to n)"""
        if n <= 0:
            return 0

        total = 0
        length = 1

        while True:
            start = 10**(length - 1)
            end = min(n, 10**length - 1)
            if end < start:
                break
            total += (end - start + 1) * length
            length += 1

        return total

    def cumulative_blocks(m):
        """Total digits in blocks 1 through m"""
        if m <= 0:
            return 0

        total = 0
        d = 1
        start = 1

        while start <= m:
            range_start = start
            range_end = min(m, 10**d - 1)

            if range_end < range_start:
                break

            count = range_end - range_start + 1
            sum_j = (range_start + range_end) * count // 2

            total += d * (count * (m + 1) - sum_j)

            d += 1
            start = 10**(d - 1)

        return total

    def find_kth(k):
        # Binary search for the block containing the k-th digit
        lo, hi = 1, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if cumulative_blocks(mid) >= k:
                hi = mid
            else:
                lo = mid + 1

        block = lo
        prev = cumulative_blocks(block - 1)
        pos = k - prev  # position within block (1-indexed)

        # Binary search to find which number in block contains digit
        lo, hi = 1, block
        while lo < hi:
            mid = (lo + hi) // 2
            if count_digits_upto(mid) >= pos:
                hi = mid
            else:
                lo = mid + 1

        num = lo
        offset = pos - count_digits_upto(num - 1) - 1

        return str(num)[offset]

