def mod_pow(base, exp, mod):
    """Calculate (base^exp) % mod using modular exponentiation"""
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

def is_prime(n):
    """Check if n is prime"""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def factorize(n):
    """Return prime factorization of n"""
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def has_order(cand, order, factors, p):
    """
    Check if cand has exactly order 'order' modulo p.
    We already know ord(cand, p) divides (p-1).
    We check that for all prime factors f of (p-1), cand^((p-1)/f) != 1 (mod p)
    """
    if cand % p == 1:
        return False
    exp = order
    for f in factors:
        if exp % f == 0:
            actual_exp = exp // f
            if mod_pow(cand, actual_exp, p) == 1:
                return False
    return True

