def is_geometric(seq):
    """Check if a sequence is a geometric progression."""
    n = len(seq)
    if n <= 2:
        return True

    # All zeros is a GP
    if all(x == 0 for x in seq):
        return True

    # Find first non-zero element
    first_nonzero_idx = None
    for i in range(n):
        if seq[i] != 0:
            first_nonzero_idx = i
            break

    if first_nonzero_idx is None:
        return True

    # Count non-zero elements
    non_zero_count = sum(1 for x in seq if x != 0)

    # 0 or 1 or 2 non-zero elements is always a GP
    if non_zero_count <= 2:
        return True

    # Calculate common ratio from first two non-zero elements
    s = seq[first_nonzero_idx]  # first non-zero value
    if first_nonzero_idx + 1 < n and seq[first_nonzero_idx + 1] != 0:
        r = seq[first_nonzero_idx + 1] / s
    else:
        return False  # Not a valid GP

    # Verify all subsequent non-zero elements follow the GP
    for i in range(first_nonzero_idx + 1, n):
        if seq[i] != 0:
            k = i - first_nonzero_idx  # position relative to first non-zero
            expected = s * (r ** k)
            if abs(seq[i] - expected) > 1e-9:
                return False

    return True

