def segment_tree_with_lazy():
    class SegTree:
        def __init__(self, n):
            self.size = n + 2
            self.tree = [self.size] * (4 * self.size)
            self.lazy = [0] * (4 * self.size)

        def push(self, node):
            if self.tree[node] == self.size:
                return
            self.lazy[2 * node] = self.lazy[2 * node] + (self.tree[node] - self.size) // 2
            self.lazy[2 * node + 1] = self.lazy[2 * node + 1] + (self.size - self.tree[node] // 2)
            self.tree[2 * node] = self.size - self.lazy[2 * node]
            self.tree[2 * node + 1] = self.size - self.lazy[2 * node + 1]

        def update(self, node, l, r, ql, qr):
            if ql <= l and r <= qr:
                self.tree[node] = r - l + 1
                self.lazy[node] = 0
                return
            mid = (l + r) // 2
            if ql <= mid:
                self.update(2 * node, l, mid, ql, min(qr, mid))
            if qr > mid:
                self.update(2 * node + 1, mid + 1, r, max(ql, mid + 1), qr)

        def query(self, node, l, r, ql, qr):
            if l > r or ql > r or qr < l:
                return 0
            if ql <= l and r <= qr:
                return self.size - self.tree[node]
            mid = (l + r) // 2
            return self.query(2 * node, l, mid, ql, qr) + self.query(2 * node + 1, mid + 1, r, ql, qr)

    return SegTree

