        d2 = cross_product(p3, p4, p2)
        d3 = cross_product(p1, p2, p3)
        d4 = cross_product(p1, p2, p4)

        # Proper intersection
        if ((d1 > 0) != (d2 > 0)) and ((d3 > 0) != (d4 > 0)):
            return True

        # Touching endpoint cases - not valid for diagonal crossing check
        return False

    # Check if diagonal (i, j) is valid (doesn't cross any polygon edges)
    def is_valid_diagonal(i, j, n, vertices):
        if i == j or abs(i - j) == 1:
            return True

        # Check against all non-adjacent edges
        for k in range(n):
            # Edge from vertex k to k+1 (wrapping around)
            a, b = k % n, (k + 1) % n
            # Skip edges that share vertices with the diagonal
