                continue

            if segments_intersect(vertices[i], vertices[j], vertices[a], vertices[b]):
                return False
        return True

    # Check if triangle is non-degenerate
    def is_valid_triangle(i, j, k, vertices):
        area = abs(vertices[i][0] * (vertices[j][1] - vertices[k][1]) +
                   vertices[j][0] * (vertices[k][1] - vertices[i][1]) +
                   vertices[k][0] * (vertices[i][1] - vertices[j][1]))
        return area > 0

    # DP table: dp[i][j] = number of triangulations of sub-polygon with vertices i, i+1, ..., j
