    for length in range(2, n):  # length from 2 to n-1 edges
        for i in range(n - length):
            j = i + length
            if j >= n:
                # Won't fit in our vertices (shouldn't happen with right bounds)
                dp[i][j] = 0
                continue

            # First, check if the diagonal (i, j) is valid for this sub-polygon
            if not is_valid_diagonal(i, j, n, vertices):
