    """
    Count valid customer queues where cinema can always provide change,
    and final 50-yuan notes is between l and r inclusive.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        lines = input_str.strip().split()[1:]

    n, p, l, r = map(int, lines[0].split())

    if n == 0:
        return "1"

    MOD = p

    # Precompute factorials for combination calculation
    max_n = n + 2
    fact = [1] * max_n
    inv = [1] * max_n

    for i in range(2, max_n):
        fact[i] = (fact[i-1] * i) % MOD

    # Compute modular inverse of factorials
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        d, x1, y1 = extended_gcd(b, a % b)
        return d, y1, x1 - (a // b) * y1

    def mod_inverse(a, m):
        d, x, y = extended_gcd(a, m)
        if d != 1:
            return None
        return x % m

    # For large MOD, many factorials will have inverses
    inv = [1] * max_n

    # Compute C(n, k) = n! / (k! * (n-k)!) % MOD
    def C(n, k):
        if k < 0 or k > n:
            return 0
        # Use extended calculation for each combination
        num = fact[n] if n < max_n else None
        if num is None:
            return 0

        den = inv[k] if inv[k] else inv_mod(k, MOD)
        if den is None:
            return 0

        den2 = inv_mod(n - k, MOD)
        if den2 is None:
            return 0

        return ((num * den) % MOD * den2) % MOD

    inv_fact = [1] * max_n
    for i in range(2, max_n):
        inv_fact[i] = mod_inverse(fact[i], MOD)

    def nCr(n, k):
        if k < 0 or k > n:
            return 0
        num = fact[n] if n < max_n else None
        if num is None:
            return 0

        den = inv[(k)] * inv[(n-k)]
        if den == 0:
            return 0

        return (fact[n] * fact[k] % MOD * fact[n-k] % MOD)

    ans = 0

    for n_A in range(n + 1):
        for n_B in range(n_A + 1):  # n_B <= n_A required for ballot theorem
            n_C = n - n_A - n_B
            if n_C < 0 or n_C > n:
                continue

            final_50 = n_A - n_B
            if final_50 < l or final_50 > r:
                continue

            # Valid A-B sequences using ballot theorem
            # ballot(n_A, n_B) = C(n_A+n_B, n_A) - C(n_A+n_B, n_A+1)
            if n_A >= n_B:
                ballot = (nCr(n_A + n_B, n_A)) - (nCr(n_A + n_B, n_A + 1) if n_A + 1 <= n_A + n_B else 0)
                ballot = ballot % MOD

                # For each valid A-B sequence, we can arrange with C's anywhere
                # = C(n, n_A+n_B) for choosing positions of A-B vs C
                arrangements = (nCr(n, n_A + n_B) * ballot) % MOD
                ans = (ans + arrangements) % MOD

    return str(ans % MOD)

