def solution(s):
    """
    Count the number of valid ways to visit k planets starting from some planet,
    where each move goes to an unvisited planet y with 1 <= y <= x + m.
    """
    line = s.strip()
    n, k, m = map(int, line.split())
    MOD = 10**9 + 7

    # Case k=1: we just choose a starting planet, n ways
    if k == 1:
        return str(n)

    # Memoized DFS to count valid paths
    @lru_cache(maxsize=None)
    def count_from(current_pos, visited_frozenset, depth):
        """
        Returns number of valid paths from current_pos, having visited planets in visited_frozenset,
        with exactly (k - depth) more planets to visit.
        """
        if depth == k:
            return 1

        count = 0
        # Can move to any unvisited planet in range [1, current_pos + m]
        limit = min(n, current_pos + m)

        for next_pos in range(1, limit + 1):
            if next_pos not in visited_frozenset and next_pos != current_pos:
                count = (count + count_from(next_pos, visited_frozenset | {next_pos}, depth + 1)) % MOD

        return count

    total = 0
    # Try each starting planet
    for start in range(1, n + 1):
        total = (total + count_from(start, {start}, 1)) % MOD

    return str(total)

