def reverse_string(s):
    """Reverse a string."""
    return s[::-1]


def flip_bits(s):
    """Flip all bits in a binary string (0->1, 1->0)."""
    return ''.join('1' if c == '0' else '0' for c in s)


def get_equivalence_class(s):
    """Get the equivalence class of a string under reversal and bit-flip."""
    class_s = set()
    class_s.add(s)
    class_s.add(reverse_string(s))
    class_s.add(flip_bits(s))
    class_s.add(flip_bits(reverse_string(s)))
    return frozenset(class_s)


