def solution(input_str):
    n, r = map(int, input_str.split())

    # Generate all valid integer points within distance r
    valid_points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                valid_points.append((x, y))

    # Sort by distance from origin (descending) to try extreme points first
    valid_points.sort(key=lambda p: p[0]**2 + p[1]**2, reverse=True)

    best_score = -float('inf')
    best_positions = []

    def calc_score(pos):
        x_sum = sum(p[0] for p in pos)
        y_sum = sum(p[1] for p in pos)
        sum_sq = sum(p[0]**2 + p[1]**2 for p in pos)
        return n * sum_sq - x_sum*x_sum - y_sum*y_sum

    def backtrack(idx, current):
        nonlocal best_score, best_positions

        if len(current) == n:
            s = calc_score(current)
            if s > best_score:
                best_score = s
                best_positions = [p[:] for p in current]
            return

        remaining = n - len(current)
        for i in range(idx, len(valid_points) - remaining + 1):
            current.append(valid_points[i])
            backtrack(i, current)
            current.pop()

    backtrack(0, [])

    lines = [str(best_score)]
    for p in best_positions:
        lines.append(f"{p[0]} {p[1]}")

    return '\n'.join(lines)

