    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    # Build adjacency list for roads
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v, x = int(parts[0]), int(parts[1]), int(parts[2])
        adj[u].append((v, x))
        adj[v].append((u, x))

    # Parse train routes
    trains = []
    for i in range(m + 1, m + k + 1):
        parts = lines[i].split()
        s, y = int(parts[0]), int(parts[1])
        trains.append((s, y))

    # Dijkstra's algorithm from city 1 using only roads
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Count removable train routes
    count = 0
    seen = set()  # Track which (city, cost) combinations we've kept

    for s, y in trains:
        # Calculate actual shortest distance from capital to city s
        # This should include train routes if they're better
        actual_dist = INF
        if trains:
            # Check train routes to this city
            for t_s, t_y in trains:
                if t_s == s:
                    actual_dist = min(actual_dist, t_y)
            # Check roads
            from collections import deque
            d = deque([(0, 1)])
            d_dist = [INF] * (n + 1)
            d_dist[1] = 0
            while d:
                cur_d, cur_u = d.popleft()
                if cur_d > d_dist[cur_u]:
                    continue
                for neighbor, w in adj[cur_u]:
                    if d_dist[cur_u] + w < d_dist[neighbor]:
                        d_dist[neighbor] = d_dist[cur_u] + w
                        d.append((d_dist[neighbor], neighbor))

            # Final shortest distance
            dist[s, y] = min(actual_dist, d_dist[s])
            if dist[s] < y:
                count += 1  # Road is better
            elif dist[s] == y:
                if (s, y) in seen or len(seen) > 0:
                    count += 1  # Redundant train
                seen.add((s, y))

    return str(count).replace('0', '0')

