    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    num_to_idx = {val: i for i, val in enumerate(p)}

    # Build dependency graph
    # forward[i] = j means a-p[i] = p[j], so if p[i]∈A then p[j]∈A
    # backward[i] = j means b-p[i] = p[j], so if p[i]∈B then p[j]∈B
    forward = {}
    backward = {}

    for i in range(n):
        if (a - p[i]) in num_to_idx:
            forward[i] = num_to_idx[a - p[i]]
        if (b - p[i]) in num_to_idx:
            backward[i] = num_to_idx[b - p[i]]

    assignment = [None] * n
    visited = set()
    valid = True

    for i in range(n):
        if valid and i not in visited:
            stack = [(i, 0)]  # (node, assigned_set): 0 for A, 1 for B
            visited.add(i)
            assignment[i] = 0

            while stack and valid:
                node, assigned_val = stack.pop()

                if node in forward:
                    target = forward[node]
                    if target not in assignment:
                        # If p[node] ∈ A, then p[target] ∈ A
                        assignment[target] = 0
                        visited.add(target)
                        stack.append((target, 0))
                    elif assignment[target] == assigned_val:
                        visited.add(target)
                        stack.append((target, assigned_val))
                if assigned_val == 1 and node in backward:
                    target = backward[node]
                    if target not in assignment:
                        assignment[target] = 1
                        visited.add(target)
                        stack.append((target, 1))

