    if not rounds:
        return "0 0\n"

    memo = {}

    def get_winner(s, e):
        if s in memo:
            return memo[s]
        if s > e:
            memo[s] = False
            return False
        if s == e:
            memo[s] = False
            return False

        can_force_win = False
        for choice in [s + 1, s * 2]:
            if choice <= e:
                if not get_winner(choice, e):
                    can_force_win = True
                    break

        memo[s] = can_force_win
        return can_force_win

    results = []
    for s, e in rounds:
        results.append(get_winner(s, e))

    current_is_lee = True
    for i in range(len(results) - 1):
        if results[i]:
            current_is_lee = not current_is_lee

    if not results:
        return "0 0\n"

    starts_last = current_is_lee
    last_result = results[-1]

    lee_can_win = last_result if starts_last else False
    lee_can_lose = not starts_last or not last_result

    return f"{1 if lee_can_win else 0}{' ' + '1' if lee_can_lose else '0'}\n"
